  (2, 5, 2), (3, 5, 2), (4, 5, 2),
  (6, 5, 3),
  (1, 6, 1), (2, 6, 1),
  (8, 5, 3);

closing.sql:
SELECT DISTINCT ON (account) account, balance AS closing
FROM fact_balance
ORDER BY account, month_end DESC;

closingTotal.sql:
SELECT SUM(closing) AS balance FROM (
  SELECT DISTINCT ON (account) balance AS closing
  FROM fact_balance ORDER BY account, month_end DESC);

stages.sql:
SELECT approved - applied AS days_to_approve,
       funded - approved AS days_to_fund
FROM fact_loan_application;

