keySize.setup:
CREATE TABLE int_keys (customer_sk bigint PRIMARY KEY);
INSERT INTO int_keys SELECT g FROM generate_series(1, 100000) g;
CREATE TABLE md5_keys (customer_sk text PRIMARY KEY);
INSERT INTO md5_keys SELECT md5(g::text) FROM generate_series(1, 100000) g;

bytes.sql:
SELECT pg_column_size(42::bigint) AS bigint_bytes,
  pg_column_size(md5('42')) AS md5_bytes,
  length(md5('42')) AS md5_chars;

index.sql:
SELECT pg_relation_size('int_keys_pkey') AS integer_index,
  pg_relation_size('md5_keys_pkey') AS md5_index,
  ROUND(pg_relation_size('md5_keys_pkey')::numeric / pg_relation_size('int_keys_pkey'), 2) AS ratio;

