unweightedTotal.sql:
SELECT SUM(f.balance) AS balance
FROM fact_account_balance f
JOIN bridge_customer_account b ON b.account_sk = f.account_sk;

weightedTotal.sql:
SELECT SUM(f.balance * b.ownership_pct)::numeric(10,2) AS balance
FROM fact_account_balance f
JOIN bridge_customer_account b ON b.account_sk = f.account_sk;
